   240→/**
   241→ * Ejecutar la acción cuando la petición no es exitosa.
   242→ *
   243→ * @param {Object} respuesta Respuesta de la solicitud.
   244→ * @returns {Promise<Array>}
   245→ * @author Andres Gonzalez
   246→ * @author Jair Carvajal
   247→ */
   248→function postError(respuesta) {
   249→    if (respuesta.errors) {
   250→        let errores_mostrados = false;
   251→
   252→        if (Array.isArray(respuesta.errors) && respuesta.errors.length > 0) {
   253→            respuesta.errors.forEach((error) => {
   254→                mostrarToast('danger', error);
   255→            });
   256→            errores_mostrados = true;
   257→        }
   258→        else if (typeof respuesta.errors === 'object' && Object.keys(respuesta.errors).length > 0) {
   259→            Object.values(respuesta.errors).forEach((error_mensajes) => {
   260→                if (Array.isArray(error_mensajes)) {
   261→                    error_mensajes.forEach((mensaje) => {
   262→                        mostrarToast('danger', mensaje);
   263→                    });
   264→                } else {
   265→                    mostrarToast('danger', error_mensajes);
   266→                }
   267→            });
   268→            errores_mostrados = true;
   269→        }
   270→
   271→        if (!errores_mostrados && respuesta.message) {
   272→            mostrarToast('danger', respuesta.message);
   273→        }
   274→    } else if (respuesta.message) {
   275→        mostrarToast('danger', respuesta.message);
   276→    } else {
   277→        mostrarToast('danger', 'Ocurrió un error al procesar la solicitud.');
   278→    }
   279→}
