   836→/**
   837→ * Función para ver el certificado de estudio en una nueva ventana.
   838→ * 
   839→ * @param {number} index Índice del nivel educativo cuyo certificado se desea ver.
   840→ * @return {void}
   841→ * @author José Manuel Jiménez
   842→ */
   843→function verCertificadoEstudio(index) {
   844→    let certificado = estudios[index].certificado;
   845→    if (certificado) {
   846→        try {
   847→            let certificado_base64 = certificado.split(',')[1] || certificado;
   848→            const binaryString = atob(certificado_base64);
   849→            const bytes = new Uint8Array(binaryString.length);
   850→            for (let i = 0; i < binaryString.length; i++) {
   851→                bytes[i] = binaryString.charCodeAt(i);
   852→            }
   853→            let blob = new Blob([bytes], { type: 'application/pdf' });
   854→            let url = URL.createObjectURL(blob);
   855→            let nuevaVentana = window.open(url, '_blank');
   856→            if (nuevaVentana) {
   857→                nuevaVentana.onload = function() {
   858→                    setTimeout(() => URL.revokeObjectURL(url), 1000);
   859→                };
   860→            }
   861→        } catch (error) {
   862→            mostrarToast('danger', 'Error al abrir el certificado.', '', '', 'bi bi-exclamation-lg');
   863→        }
   864→    } else {
   865→        mostrarToast('danger', 'No se encontró el certificado de estudio.', '', '', 'bi bi-exclamation-lg');
   866→    }
   867→}
