  1412→    $input_hasta.removeClass('error');
  1413→    $contenedor_hasta.siblings('label[for="salario_maximo"].error').remove();
  1414→    if (salario_desde > 99 && salario_maximo > 99 && salario_desde >= salario_maximo) {
  1415→        setTimeout(() => {
