$(document).ready(function () {
    configurarFormulario("formulario-creacion-aplicante");
    configurarFormulario("formulario-nivel-educativo");
    configurarFormulario("formulario-experiencia-laboral");
    configurarFormulario("formulario-perfiles-laborales");
    moment.locale('es');

    $('#password').on('input', function() {
        var contrasena = $(this).val();

        // Validar longitud (mínimo 8)
        estado_validacion_contrasena.longitud_minima = contrasena.length >= 8;
        actualizarElementoValidacion('longitud-contrasena', estado_validacion_contrasena.longitud_minima);

        // Validar mayúscula
        estado_validacion_contrasena.letra_mayuscula = /[A-Z]/.test(contrasena);
        actualizarElementoValidacion('mayuscula-contrasena', estado_validacion_contrasena.letra_mayuscula);

        // Validar minúscula
        estado_validacion_contrasena.letra_minuscula = /[a-z]/.test(contrasena);
        actualizarElementoValidacion('minuscula-contrasena', estado_validacion_contrasena.letra_minuscula);

        // Validar número
        estado_validacion_contrasena.tiene_numero = /\d/.test(contrasena);
        actualizarElementoValidacion('numero-contrasena', estado_validacion_contrasena.tiene_numero);

        // Validar carácter especial
        estado_validacion_contrasena.caracter_especial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(contrasena);
        actualizarElementoValidacion('caracter-especial-contrasena', estado_validacion_contrasena.caracter_especial);

        verificarCoincidenciaContrasenas();
        verificarTodasLasValidacionesContrasena();
    });

    $('#password_confirmation').on('input', function() {
        verificarCoincidenciaContrasenas();
        verificarTodasLasValidacionesContrasena();
    });

    verificarTodasLasValidacionesContrasena();
    inputsCleave();
    actualizarSelect2();
    inizializarMultiselect();
    inicializarTooltips();
    inicializarIputsFile();
});

