/**
 * Función para enviar una notificación de un código para verificar el usuario.
 * 
 * @param {string} tipo_verificacion Tipo de verificación (correo o celular).
 * @returns {void}
 * @author José Manuel Jiménez
 */
function enviarVerificacion(tipo_verificacion) {
    let email = $('#email').val();
    let expresion_regular_email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (expresion_regular_email.test(email) && email.length > 0) {
        if (typeof USUARIO !== 'undefined') {
            $.ajax({
                type: 'POST',
                url : '/enviar-codigo-autorizacion',
                data: {
                    _token: $('meta[name="csrf-token"]').attr('content'),
                    id    : USUARIO.id,
                    email : email
                }
            }).done(function (respuesta) {
                mostrarAlertasCodigoEnviado();
            }).fail(function (error) {
                $('#alerta-exito').removeClass('d-block').addClass('d-none');
                $('#alerta-error').removeClass('d-none').addClass('d-block');
                $('#alerta-error').html('Ocurrio un error al intentar enviar el código de verificación por correo electrónico.');
                console.error(error);
            });
        } else {
            $.ajax({
                type: 'POST',
                url : '/portales-empleo-enviar-codigo-autorizacion',
                data: {
                    _token: $('meta[name="csrf-token"]').attr('content'),
                    email : $('#email').val()
                }
            }).done(function (respuesta) {
                respuesta_codigo = respuesta.respuesta;
                mostrarAlertasCodigoEnviado();
            }).fail(function (error) {
                console.error(error);
            });
        }
    } else {
        mostrarToast('danger', 'Por favor, ingresa un correo electrónico válido.', '', '', 'bi bi-exclamation-lg');
    }
}

/**
 * Función para mostrar las alertas cuando se ha enviado el código de confirmación.
 * 
 * @returns {void}
 * @author José Manuel Jiménez
 */
function mostrarAlertasCodigoEnviado() {
    $('#contenedor-mensaje-verificar').addClass('d-none');
    $('#contenedor-mensaje-enviado').removeClass('d-none');
    $('#contenedor-info-mensaje-enviado').removeClass('d-none');
    $('#contenedor-codigo-confirmacion').removeClass('d-none col-lg-6');
    $('#contenedor-reenviar-mensaje').addClass('d-none');
    $('.boton-verificacion').prop('disabled', true);
    let segundos_para_reenviar = 59;
    let intervalo = setInterval(function () {
    $('#contador-segundos').text(segundos_para_reenviar);
        if (segundos_para_reenviar <= 0) {
            clearInterval(intervalo);
            if (!usuario_verificado) {
                $('.boton-verificacion').prop('disabled', false);
                $('#contenedor-info-mensaje-enviado').addClass('d-none');
                $('#contenedor-mensaje-enviado').addClass('d-none');
                $('#contenedor-reenviar-mensaje').removeClass('d-none');
                $('#contenedor-codigo-confirmacion').addClass('col-lg-6');
                $('#contenedor-boton-reenviar-mensaje').removeClass('d-none');
            }
        }
        segundos_para_reenviar--;
    }, 1000);
}

/**
 * Función para validar el código de confirmación ingresado por el usuario.
 * 
 * @param {string} codigo Código de confirmación ingresado por el usuario.
 * @return {void}
 * @author José Manuel Jiménez
 */
function validarCodigoConfirmacion(codigo) {
    if (codigo.length == 6) {
        $('#contenedor-codigo-incorrecto').addClass('d-none');
        if (typeof USUARIO !== 'undefined') {
            if (!validando_codigo) {
                validando_codigo = true;
                $.ajax({
                    type: 'POST',
                    url : '/verificar-codigo-autorizacion',
                    data: {
                        _token: $('meta[name="csrf-token"]').attr('content'),
                        id    : USUARIO.id,
                        codigo: codigo
                    }
                }).done(function (respuesta) {
                    validando_codigo = false;
                    if (respuesta.message === 'El código no es válido') {
                        $('#contenedor-codigo-incorrecto').removeClass('d-none');
                    } else {
                        mostrarAlertasUsuarioVerificado();
                    }
                }).fail(function (error) {
                    mostrarToast('danger', 'Ocurrió un error al intentar verificar el código de autorización.', '', '', '');
                });
            }
        } else {
            if (codigo == respuesta_codigo.codigo_autorizacion) {
                mostrarAlertasUsuarioVerificado();
            } else {
                $('#contenedor-codigo-incorrecto').removeClass('d-none');
            }
        }
    } else {
        $('#contenedor-codigo-incorrecto').addClass('d-none');
    }
}

