/**
 * Ejecutar la acción cuando la petición no es exitosa.
 *
 * @param {Object} respuesta Respuesta de la solicitud.
 * @returns {Promise<Array>}
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function postError(respuesta) {
    if (respuesta.errors) {
        let errores_mostrados = false;

        if (Array.isArray(respuesta.errors) && respuesta.errors.length > 0) {
            respuesta.errors.forEach((error) => {
                mostrarToast('danger', error);
            });
            errores_mostrados = true;
        }
        else if (typeof respuesta.errors === 'object' && Object.keys(respuesta.errors).length > 0) {
            Object.values(respuesta.errors).forEach((error_mensajes) => {
                if (Array.isArray(error_mensajes)) {
                    error_mensajes.forEach((mensaje) => {
                        mostrarToast('danger', mensaje);
                    });
                } else {
                    mostrarToast('danger', error_mensajes);
                }
            });
            errores_mostrados = true;
        }

        if (!errores_mostrados && respuesta.message) {
            mostrarToast('danger', respuesta.message);
        }
    } else if (respuesta.message) {
        mostrarToast('danger', respuesta.message);
    } else {
        mostrarToast('danger', 'Ocurrió un error al procesar la solicitud.');
    }
}


