/**
 * Función para validar el formulario antes de enviarlo.
 *
 * @param {Object} formulario Formulario a validar.
 * @returns {boolean} Retorna true si el formulario es válido, de lo contrario false.
 * @author José Manuel Jiménez
  * @author Andres Gonzalez
 */
function validacionAdicional(formulario) {
    let valido = true;
    if (formulario == 'formulario-nivel-educativo') {
        let errores = $('#formulario-nivel-educativo').find('input.error , select.error , textarea.error');
        if (errores.length == 0) {
            let fecha_inicio = $('#fecha_inicio_estudio').val() ? moment($('#fecha_inicio_estudio').val(), 'YYYY-MM-DD') : null;
            let fecha_fin = $('#fecha_fin_estudio').val() ? moment($('#fecha_fin_estudio').val(), 'YYYY-MM-DD') : null;
            let fecha_actual = moment();
            if (fecha_inicio && fecha_inicio.isAfter(fecha_actual)) {
                mostrarToast('danger', 'La fecha de inicio del estudio no puede ser una fecha futura.');
                valido = false;
            } else if (fecha_fin && fecha_fin.isAfter(fecha_actual)) {
                mostrarToast('danger', 'La fecha de finalización del estudio no puede ser una fecha futura.');
                valido = false;
            } else if (fecha_inicio && fecha_fin && fecha_fin.isBefore(fecha_inicio)) {
                mostrarToast('danger', 'La fecha de finalización del estudio no puede ser anterior a la fecha de inicio.');
                valido = false;
            } else {
                let estudio = {
                    titulo: $('#titulo').val(),
                    institucion_educativa: $('#institucion_educativa').val(),
                    nivel_educativo_id: parseInt($('#nivel_educativo_id').val()),
                    nivel_educativo: $('#nivel_educativo_id option:selected').text().trim(),
                    graduado: $('#cursando_estudios').prop('checked') ? false : true,
                    fecha_inicio: $('#fecha_inicio_estudio').val(),
                    fecha_fin: $('#fecha_fin_estudio').val() || null,
                    jornada: $('#jornada').val() || null,
                }
                if (indice_editar == null) {
                    estudios.push(estudio);
                } else {
                    estudios[indice_editar] = estudio;
                    indice_editar = null;
                }
                mostrarNivelesEducativos();
                $('#modal-agregar-nivel-educativo').modal('hide');
                limpiarFormulario('formulario-nivel-educativo');
                mostrarToast('success', 'Nivel educativo agregado exitosamente.');
                setTimeout(() => {
                    $('#formulario-nivel-educativo').find('input.error , select.error , textarea.error').removeClass('error');
                    $('#formulario-nivel-educativo').find('label.error').remove();
                }, 100);
            }
        } else {
            mostrarToast('danger', 'Faltan datos obligatorios. Revisa la información e inténtalo de nuevo.');
        }
        valido = false;
    } else if (formulario == 'formulario-experiencia-laboral') {
        let errores = $('#formulario-experiencia-laboral').find('input.error , select.error , textarea.error');
        if (errores.length == 0) {
            let fecha_inicio = $('#fecha_inicio_experiencia').val() ? moment($('#fecha_inicio_experiencia').val(), 'YYYY-MM-DD') : null;
            let fecha_fin = $('#fecha_fin_experiencia').val() ? moment($('#fecha_fin_experiencia').val(), 'YYYY-MM-DD') : null;
            let fecha_actual = moment();
            if (fecha_inicio && fecha_inicio.isAfter(fecha_actual)) {
                mostrarToast('danger', 'La fecha de inicio de la experiencia laboral no puede ser una fecha futura.');
                valido = false;
            } else if (fecha_fin && fecha_fin.isAfter(fecha_actual)) {
                mostrarToast('danger', 'La fecha de finalización de la experiencia laboral no puede ser una fecha futura.');
                valido = false;
            } else if (fecha_inicio && fecha_fin && fecha_fin.isBefore(fecha_inicio)) {
                mostrarToast('danger', 'La fecha de finalización de la experiencia laboral no puede ser anterior a la fecha de inicio.');
                valido = false;
            } else {
                let experiencia = {
                    cargo: $('#cargo').val(),
                    empresa: $('#empresa').val(),
                    actualmente_trabajo: $('#actualmente_trabajo').prop('checked') ? 1 : 0,
                    fecha_inicio: $('#fecha_inicio_experiencia').val(),
                    fecha_fin: $('#fecha_fin_experiencia').val() || null,
                    funciones: $('#funciones_experiencia').val(),
                }
                if (indice_editar == null) {
                    experiencias.push(experiencia);
                } else {
                    experiencias[indice_editar] = experiencia;
                    indice_editar = null;
                    certificados_laborales = [];
                }
                mostrarExperienciasLaborales();
                $('#modal-agregar-experiencia-laboral').modal('hide');
                limpiarFormulario('formulario-experiencia-laboral');
                mostrarToast('success', 'Experiencia laboral agregada exitosamente.');
                setTimeout(() => {
                    $('#formulario-experiencia-laboral').find('input.error , select.error , textarea.error').removeClass('error');
                    $('#formulario-experiencia-laboral').find('label.error').remove();
                }, 100);
            }
        } else {
            mostrarToast('danger', 'Faltan datos obligatorios. Revisa la información e inténtalo de nuevo.');
        }
        valido = false;
    } else {
        let formulario_actual = $('#formulario .nav-pasos.active').first();
        let id_formulario_actual = $(formulario_actual).attr('href');
        let errores = $(id_formulario_actual).find('input.error , select.error , textarea.error');
        if (id_formulario_actual == '#tab-pasos-usuario-datos-generales') {
            let politicas_aceptadas = $('#aceptar_politicas').is(':checked');
            if (!politicas_aceptadas) {
                mostrarToast('danger', 'Debes aceptar las políticas de tratamiento de datos personales.', '', '', 'bi bi-exclamation-lg');
            }
            valido = false;
        } else if (id_formulario_actual == '#tab-pasos-usuario-datos-acceso') {
            if (validar_contrasena) {
                if (!usuario_verificado && valido) {
                    mostrarToast('danger', 'Debes verificar tu cuenta antes de continuar.', '', '', 'bi bi-exclamation-lg');
                    valido = false;
                }
                if (Object.values(estado_validacion_contrasena).includes(false) && valido) {
                    mostrarToast('danger', 'Tu contraseña no cumple con todos los requisitos de seguridad. Por favor, revisa los elementos marcados en rojo.', '', '', 'bi bi-exclamation-lg');
                    valido = false;
                }
            } else {
                valido = false;
            }
        } else if (id_formulario_actual == '#tab-pasos-usuario-perfil-laboral') {
            if (errores.length > 0) {
                mostrarToast('danger', 'Faltan algunos datos obligatorios. Por favor, revisa la información e intenta nuevamente');
                valido = false;
            }
            let salario = parseFloat(limpiarCleave($('#salario').val())) || 0;
            if (salario < 0) {
                mostrarToast('danger', 'El salario no puede ser un valor negativo.');
                valido = false;
            }
            if ($('#salario_maximo').length > 0) {
                let salario_maximo = parseFloat(limpiarCleave($('#salario_maximo').val())) || 0;
                if (salario_maximo < 0) {
                    mostrarToast('danger', 'El salario máximo no puede ser un valor negativo.');
                    valido = false;
                }
                if (salario_maximo < salario) {
                    if (salario_maximo > 0) {
                        mostrarToast('danger', 'El salario máximo no puede ser menor que el salario mínimo.');
                    }
                    valido = false;
                }
            }
            validarRangoSalario();
            let habilidades_seleccionadas = $('#select_habilidades').val();
            $('#habilidades').val(Array.isArray(habilidades_seleccionadas) ? habilidades_seleccionadas.join(', ') : '');
            let herramientas_seleccionadas = $('#select_herramientas_tecnologicas').val();
            $('#herramientas_tecnologicas').val(Array.isArray(herramientas_seleccionadas) ? herramientas_seleccionadas.join(', ') : '');
            $('#estudios').val(JSON.stringify(estudios.map(({ nivel_educativo, graduado, ...estudio }) => estudio)));
            if ($('#no_experiencia').is(':checked')) {
                $('#experiencias_laborales').val('');
            } else {
                $('#experiencias_laborales').val(JSON.stringify(experiencias.map(({ actualmente_trabajo, ...experiencia }) => experiencia)));
            }
            let idiomas = $('.idioma');
            let niveles = $('.nivel-idioma');
            let idiomas_seleccionados = [];
            for (let i = 0; i < idiomas.length; i++) {
                idiomas_seleccionados.push({
                    idioma_id: parseInt($(idiomas[i]).val()),
                    nivel    : $(niveles[i]).val()
                });
            }
            if (idiomas_seleccionados.length == 0) {
                $('#idiomas').val('');
            } else {
                $('#idiomas').val(JSON.stringify(idiomas_seleccionados));
            }
            let discapacidades_seleccionadas = $('#select_discapacidades').val();
            let discapacidades_finales = [];
            if (discapacidades_seleccionadas) {
                discapacidades_seleccionadas.forEach(discapacidad_id => {
                    let discapacidad = discapacidades.find(d => d.id == discapacidad_id);
                    if (discapacidad) {
                        let otra_discapacidad = null;
                        if (discapacidad.id == '5') {
                            otra_discapacidad = $('#otra_discapacidad').val().trim();
                        }
                        discapacidades_finales.push({
                            usuario_id: USUARIO.id,
                            discapacidad_id: parseInt(discapacidad_id),
                            otra_discapacidad: otra_discapacidad
                        });
                    }
                });
                $('#discapacidades').val(JSON.stringify(discapacidades_finales));
            } else {
                $('#discapacidades').val('');
            }

            if (estudios.length == 0) {
                mostrarToast('danger', 'Debes agregar al menos un nivel educativo para continuar.');
                valido = false;
            }

            // Validar que todos los estudios tengan fecha de inicio
            for (let i = 0; i < estudios.length; i++) {
                let estudio = estudios[i];
                if (!estudio.fecha_inicio || estudio.fecha_inicio.trim() === '') {
                    mostrarToast('danger', `El estudio "${estudio.titulo || 'Sin título'}" requiere una fecha de inicio.`);
                    valido = false;
                    break;
                }
            }

            if (experiencias.length == 0 && !$('#no_experiencia').is(':checked')) {
                mostrarToast('danger', 'Debes agregar al menos una experiencia laboral para continuar.');
                valido = false;
            }
        }
    }
    return valido;
}

