function editarNivelEducativo(index) {
    indice_editar = index;
    let estudio = estudios[index];
    $('#titulo').val(estudio.titulo);
    $('#institucion_educativa').val(estudio.institucion_educativa);
    $('#cursando_estudios').prop('checked', !estudio.graduado).trigger('change');
    $('#nivel_educativo_id').val(estudio.nivel_educativo_id).trigger('change');
    $('#fecha_inicio_estudio')[0]._flatpickr.setDate(estudio.fecha_inicio);
    if ($('#fecha_fin_estudio').length > 0) {
        $('#fecha_fin_estudio')[0]._flatpickr.setDate(estudio.fecha_fin || '');
    }
    $('#jornada').val(estudio.jornada || '').trigger('change');
    establecerDatosComponentePaisesDepartamentosCiudades({
        pais: { html_id: 'estudio_pais_id', value: estudio.pais_id },
