function eliminarNivelEducativo(index) {
    estudios.splice(index, 1);
    mostrarNivelesEducativos();
}

/**
 * Función para ver el certificado de estudio en una nueva ventana.
 * 
 * @param {number} index Índice del nivel educativo cuyo certificado se desea ver.
 * @return {void}
 * @author José Manuel Jiménez
 */
function verCertificadoEstudio(index) {
    let certificado = estudios[index].certificado;
    if (certificado) {
        try {
            let certificado_base64 = certificado.split(',')[1] || certificado;
            const binaryString = atob(certificado_base64);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            let blob = new Blob([bytes], { type: 'application/pdf' });
            let url = URL.createObjectURL(blob);
            let nuevaVentana = window.open(url, '_blank');
            if (nuevaVentana) {
                nuevaVentana.onload = function() {
                    setTimeout(() => URL.revokeObjectURL(url), 1000);
                };
            }
        } catch (error) {
            mostrarToast('danger', 'Error al abrir el certificado.', '', '', 'bi bi-exclamation-lg');
        }
    } else {
        mostrarToast('danger', 'No se encontró el certificado de estudio.', '', '', 'bi bi-exclamation-lg');
    }
}

