/**
 * Función para agregar o editar una experiencia laboral.
 * 
 * @param {number|null} index Índice de la experiencia laboral a editar. Si es null, se agrega una nueva experiencia laboral.
 * @return {void}
 * @author José Manuel Jiménez
 * @author Jair Carvajal
 */
function mostrarExperienciasLaborales() {
    $('#contenedor-experiencias-laborales').empty();
    if (experiencias.length > 0) {
        $('#no_experiencia').prop('disabled', true);
        // Ordenar experiencias usando función global reutilizable
        let experiencias_ordenadas = ordenarExperienciasPorFecha(experiencias);

        experiencias_ordenadas.forEach((experiencia) => {
            $('#contenedor-experiencias-laborales').append(`
                <div class="col-12 pt-3 px-3 mt-4 border rounded-3" id="nivel-educativo-${experiencia.indice_original}">
                    <div class="row mb-2">
                        <div class="col-lg">
                            <p class="mb-1 fw-bold text-gray-20">${experiencia.cargo}</p>
                            <p class="text-body-3 mb-2">
                                ${experiencia.fecha_inicio || experiencia.fecha_fin ? `<i class="bi bi-calendar4 text-headline-5 me-2"></i>` : ''}
                                ${
                                    experiencia.fecha_inicio
                                    ? moment(experiencia.fecha_inicio).format("MMM YYYY") +
                                        (experiencia.fecha_fin
                                        ? ` - ${moment(experiencia.fecha_fin).format("MMM YYYY")}`
                                        : " - Actualmente")
                                    : ""
                                }
                                ${
                                    experiencia.fecha_inicio && experiencia.fecha_fin
                                    ? (() => {
                                        let inicio = moment(experiencia.fecha_inicio);
                                        let fin = moment(experiencia.fecha_fin);

                                        let anios = fin.diff(inicio, 'years');
                                        let meses = fin.diff(inicio.add(anios, 'years'), 'months');

                                        let texto = '';
                                        if (anios > 0) texto += `${anios} año${anios > 1 ? 's' : ''}`;
                                        if (meses > 0) texto += `${anios > 0 ? ' y ' : ''}${meses} mes${meses > 1 ? 'es' : ''}`;

                                        return texto ? ` | ${texto}` : '';
                                        })()
                                    : ''
                                }
                            </p>
                            <p class="text-body-3 mb-1 fw-semibold text-gray-10">${experiencia.empresa}</p>
                            ${experiencia.funciones ? `
                                <p class="text-body-2 fw-semibold text-gray-10 mt-3 mb-0">Funciones y responsabilidades</p>
                                <div class="w-100 text-body-3">${experiencia.funciones}</div>
                            `
                            : ''}
                        </div>
                        <div class="col-auto">
                            <div class="row justify-content-end">
                                <div class="col-auto ps-0">
                                    ${crearBoton({
                                        clases: 'btn-outline-primary btn-circle',
                                        texto: '<i class="bi bi-pencil-fill"></i>',
                                        onclick: `editarExperienciaLaboral(${experiencia.indice_original})`
                                    })}
                                </div>
                                <div class="col-auto ps-0">
                                    ${crearBoton({
                                        clases: 'btn-outline-danger btn-circle',
                                        texto: '<i class="bi bi-trash-fill"></i>',
                                        onclick: `eliminarExperienciaLaboral(${experiencia.indice_original})`
                                    })}
                                </div>
                            </div>
                        </div>
                        ${experiencia.funciones_principales ? `
                            <div class="col-12 mt-5 mb-3 text-body-2 fw-semibold text-gray-10">Funciones principales</div>
                            <div class="col-12">${experiencia.funciones_principales}</div>
                        ` : ''}
                    </div>
                </div>
            `);
        });
    } else {
        $('#no_experiencia').prop('disabled', false);
    }
}

