/**
 * Función para actualizar el estado visual de una validación de contraseña.
 * 
 * @return {void}
 * @author Andres Gonzalez
 */
function actualizarElementoValidacion(elemento_id, es_valido) {
    const elemento_validacion = $('#' + elemento_id);
    const icono_validacion = elemento_validacion.find('i');

    if (es_valido) {
        elemento_validacion.removeClass('invalido').addClass('valido');
        icono_validacion.removeClass('bi-x-circle').addClass('bi-check-circle');
    } else {
        elemento_validacion.removeClass('valido').addClass('invalido');
        icono_validacion.removeClass('bi-check-circle').addClass('bi-x-circle');
    }
}
/**
 * Función para verificar si todas las validaciones de la contraseña pasan.
 * 
 * @return {void}
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function verificarTodasLasValidacionesContrasena() {
    if (!validar_contrasena) {
        $('#btn-datos-acceso').prop('disabled', false);
        return;
    }

    var todas_las_validaciones_pasan = Object.values(estado_validacion_contrasena).every(estado_item => estado_item === true);
    $('#submit-btn').prop('disabled', !todas_las_validaciones_pasan);

    if (todas_las_validaciones_pasan) {
        $('#btn-datos-acceso').prop('disabled', false);
        $('#submit-btn').removeClass('btn-secondary').addClass('btn-success');
    } else {
        $('#btn-datos-acceso').prop('disabled', true);
        $('#submit-btn').removeClass('btn-success').addClass('btn-primary');
    }
}

/**
 * Función para verificar coincidencia de contraseñas.
 * 
 * @return {void}
 * @author Andres Gonzalez
 */
function verificarCoincidenciaContrasenas() {
    const contrasena_original = $('#password').val();
    const contrasena_confirmacion = $('#password_confirmation').val();

    if (contrasena_confirmacion.length > 0) {
        estado_validacion_contrasena.contrasenas_coinciden = contrasena_original === contrasena_confirmacion && contrasena_original.length > 0;
        actualizarElementoValidacion('contrasena-igual', estado_validacion_contrasena.contrasenas_coinciden);
    } else {
        estado_validacion_contrasena.contrasenas_coinciden = false;
        actualizarElementoValidacion('contrasena-igual', false);
    }
}

/**
