 * @description Verifica que el salario máximo sea mayor o igual al salario mínimo
 * @returns {boolean} true si es válido, false en caso contrario
 * @author José Manuel Jiménez
 */
function validarRangoSalario() {
    if ($('input[name="tipo_salario"]:checked').val() !== 'rango') {
        return true;
    }
    let salario_desde = parseFloat(limpiarCleave($('#salario').val())) || 0;
    let salario_maximo = parseFloat(limpiarCleave($('#salario_maximo').val())) || 0;
    let $input_hasta = $('#salario_maximo');
    let $contenedor_hasta = $input_hasta.closest('.input-container');
    $input_hasta.removeClass('error');
    $contenedor_hasta.siblings('label[for="salario_maximo"].error').remove();
    if (salario_desde > 99 && salario_maximo > 99 && salario_desde >= salario_maximo) {
