function restaurarBorrador() {
    var clave_borrador = 'borrador_completar_datos_' + USUARIO.id;
     var borrador = localStorage.getItem(clave_borrador);
      if (!borrador) return false;

      var datos = JSON.parse(borrador);
      var tiempo_expiracion = 24 * 60 * 60 * 1000; // 24 horas

      if (Date.now() - datos.timestamp > tiempo_expiracion) {
          localStorage.removeItem(clave_borrador);
          return false;
      }

      // Restaurar paso 1 - Datos Generales
      if (datos.datos_generales) {
          $('#nombres').val(datos.datos_generales.nombres || '');
          $('#apellidos').val(datos.datos_generales.apellidos || '');
          $('#telefono').val(datos.datos_generales.telefono || '');
          $('#direccion').val(datos.datos_generales.direccion || '');

          if (datos.datos_generales.fecha_nacimiento) {
              $('#fecha_nacimiento')[0]._flatpickr?.setDate(datos.datos_generales.fecha_nacimiento);
          }
          if (datos.datos_generales.genero_id) {
              $('#genero_id').val(datos.datos_generales.genero_id).trigger('change');
          }
          if (datos.datos_generales.tipo_documento_id) {
              $('#tipo_documento_id').val(datos.datos_generales.tipo_documento_id).trigger('change');
          }
          $('#documento').val(datos.datos_generales.documento || '');

          // Restaurar ubicación
          if (datos.datos_generales.pais_id) {
              establecerDatosComponentePaisesDepartamentosCiudades({
                  pais: { html_id: 'pais_id', value: datos.datos_generales.pais_id },
                  departamento: { html_id: 'departamento_id', value: datos.datos_generales.departamento_id },
                  ciudad: { html_id: 'ciudad_id', value: datos.datos_generales.ciudad_id },
              });
          }

          $('#aceptar_politicas').prop('checked', datos.datos_generales.aceptar_politicas);
          $('#aceptar_teminos_condiciones').prop('checked', datos.datos_generales.aceptar_teminos_condiciones);
          validarPoliticas();
      }

      // Restaurar estudios y experiencias
      if (datos.estudios?.length > 0) {
          estudios = datos.estudios;
          mostrarNivelesEducativos();
      }
      if (datos.experiencias?.length > 0) {
          experiencias = datos.experiencias;
          mostrarExperienciasLaborales();
      }

      // Restaurar paso actual (navegar al último paso guardado)
      if (datos.paso_actual && datos.paso_actual !== 'datos-generales') {
          // Habilitar pasos anteriores
          habilitarPasosHasta(datos.paso_actual);
      }

