                ciudad: { html_id: 'ciudad_id', value: datos.datos_generales.ciudad_id },
            });
        }

        $('#aceptar_politicas').prop('checked', datos.datos_generales.aceptar_politicas);
        $('#aceptar_teminos_condiciones').prop('checked', datos.datos_generales.aceptar_teminos_condiciones);
        validarPoliticas();

        if (datos.datos_acceso) {
            if (datos.datos_acceso.codigo_enviado && !datos.datos_acceso.usuario_verificado) {
                $('#contenedor-mensaje-verificar').addClass('d-none');
                $('#contenedor-codigo-confirmacion').removeClass('d-none');
